#app { width: 100%; }

/* The dashboard root <div class="mm-dashboard ... flex flex-col ..."> relies on
   GLOBAL UnoCSS utilities (virtual:uno.css in the real app) for the classes it
   applies to ITSELF. dashboard.css only contains descendant-scoped rules
   (.mm-dashboard .flex ...), so the root node would otherwise stay display:block,
   breaking the flex height chain and letting the ResizeObserver push charts to
   grow infinitely. Provide the root's own utility classes here. */
.mm-dashboard.flex { display: flex; }
.mm-dashboard.flex-col { flex-direction: column; }
.mm-dashboard.text-slate-800 { color: #1e293b; }

