cd 'D:\repository\门户\zhi2-web-admin\standalone-build'; @'
const { chromium } = require('playwright')
const path = require('path')
const OUT = 'D:/repository/门户/zhi2-web-admin/standalone-build/shots'
const fileUrl = 'file:///D:/repository/%E9%97%A8%E6%88%B7/zhi2-web-admin/standalone-build/market-monitor.standalone.html'
async function run(browser, w, h, file) {
  const page = await browser.newPage({ viewport: { width: w, height: h } })
  const errors = []
  page.on('pageerror', e => errors.push(e.message))
  await page.goto(fileUrl, { waitUntil: 'load' })
  const sample = () => page.evaluate(() => [...document.querySelectorAll('.mm-chart')].map(el => Math.round(el.getBoundingClientRect().height)))
  const a = await sample(); await page.waitForTimeout(1500); const b = await sample()
  await page.screenshot({ path: path.join(OUT, file) })
  await page.close()
  const drift = a.map((v,i)=>Math.abs(v-b[i]))
  return { w, h, file, chartsA: a, chartsB: b, maxDrift: Math.max(0,...drift), errors }
}
;(async () => {
  const browser = await chromium.launch({ headless: true })
  const results = []
  results.push(await run(browser, 1920, 1080, 'fixed-1920x1080.png'))
  results.push(await run(browser, 1366, 768, 'fixed-1366x768.png'))
  results.push(await run(browser, 1920, 953, 'fixed-1920x953.png'))
  await browser.close()
  console.log(JSON.stringify(results, null, 2))
})().catch(e=>{console.error(e);process.exit(1)})
